{
  "name": "pairwise_advantage_cost_loss",
  "intuition": "This loss leverages advantage differences combined with cost gaps to promote selections with higher advantages and lower costs. Using logsigmoid on advantage differences emphasizes the preference for better options, while the cost gap regularizes against costly choices. This encourages the model to prefer pairs where the advantaged choice also has a lower cost, aligning with lower-is-better objectives.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l + alpha * log(cost_b / cost_a + epsilon)))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "cost_gap",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "log", "exp", "add", "sub", "mul", "div", "max", "eps"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_b", "cost_a"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    epsilon = 1e-8\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_b = batch.get(\"cost_b\", 1.0)\n    cost_a = batch.get(\"cost_a\", 1.0)\n    # Compute advantage difference\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    # Compute cost ratio\n    cost_ratio = ops.div(ops.add(cost_b, epsilon), ops.add(cost_a, epsilon))\n    log_cost_ratio = ops.log(cost_ratio)\n    # Combine signals\n    combined_signal = ops.add(advantage_diff, ops.mul(extra.alpha if extra and \"alpha\" in extra else 1.0, log_cost_ratio))\n    # Compute pairwise loss\n    loss = -ops.mean(ops.logsigmoid(combined_signal))\n    return loss"
}

{
  "name": "unnamed_free_loss",
  "intuition": "Simplified and stabilized the loss by removing the detached gap term which was not part of expects and could cause instability or invalid usage. Kept only log_prob_w and log_prob_l scaled and clamped for numeric stability, summing their negative logsigmoid as a pairwise margin loss. This respects the constraints by requiring only weight, log_prob_w, log_prob_l, and cost_a and cost_b for a preference signal (cost gap). Clamping inputs to logsigmoid prevents numerical overflow and ensures stable gradients.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    scale_w = 1.0\n    scale_l = 1.0\n    x_w = ops.clamp(scale_w * lpw, -20.0, 20.0)\n    x_l = ops.clamp(scale_l * lpl, -20.0, 20.0)\n    loss_w = -ops.logsigmoid(x_w)\n    loss_l = -ops.logsigmoid(x_l)\n    combined_loss = loss_w + loss_l\n    if weight is not None:\n        combined_loss = combined_loss * weight\n    return combined_loss.mean()",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  }
}

{
  "name": "pairwise_advantage_gap_loss",
  "intuition": "This loss encourages the model to prefer pairs with higher advantage differences, scaled by the advantage gap, making it sensitive to the relative quality of options. Using advantage_gap and log probabilities emphasizes the relative preference, promoting policies that rank better options more highly. The advantage gap provides a direct measure of superiority, ensuring the loss penalizes instances where an inferior option has a higher advantage.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_gap * (log_prob_w - log_prob_l)) * weight)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "pairwise",
    "constraint_family": "margin"
  },
  "operators_used": ["logsigmoid", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_gap = batch['advantage_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    scaled_diff = ops.mul(advantage_gap, ops.sub(log_prob_w, log_prob_l))\n    loss_terms = ops.logsigmoid(scaled_diff)\n    weighted_loss = ops.mul(loss_terms, weight)\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages the model to prefer pairs with higher advantage scores and larger cost gaps, effectively combining quality and performance signals to promote better decision-making. Using logsigmoid on advantage signals emphasizes confident preferences, while weighting by cost_gap balances the importance of the pairwise differences.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l) * logsigmoid(cost_gap))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "cost_gap",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    cost_diff = ops.logsigmoid(cost_gap)\n    pairwise_adv = ops.logsigmoid(advantage_diff)\n    pairwise_cost = ops.logsigmoid(cost_diff)\n    weighted_score = ops.mul(pairwise_adv, pairwise_cost)\n    loss = ops.neg(ops.mean(weighted_score))\n    return loss"
}

{
  "name": "loss_pairwise_rankgap_tanh_advantage",
  "intuition": "This hyperparameter tuning adjusts the 'alpha' scaling factor in the tanh function to better control the smoothness of the ranking penalty based on the advantage difference and rank gap. Increasing alpha emphasizes the rank gap more strongly, while decreasing it favors more stability. It preserves the original hyperparams family tags to maintain the family structure, allowing finer control over the hyperparameter landscape. Tuning alpha improves the balance between rank preservation and gradient stability, essential for efficient training.",
  "pseudocode": "rank_gap = rank_gap(batch['log_prob_w'], batch['log_prob_l'])\nadv_w = batch['advantage_w']\nadv_l = batch['advantage_l']\nadv_diff = adv_w - adv_l\nscore = tanh(alpha * rank_gap * adv_diff)\nloss = (1 - score) * weight\nfinal_loss = mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none",
    "hyperparameter_tuning": {
      "name": "alpha",
      "value": 1.5,
      "description": "Scaling factor for the rank gap and advantage difference to control penalty sharpness."
    }
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('hyperparams', {}).get('alpha', 1.5))\n    gap = ops.rank_gap(lpw, lpl)\n    adv_diff = ops.sub(adv_w, adv_l)\n    scaled = ops.mul(ops.mul(alpha, gap), adv_diff)\n    score = ops.tanh(scaled)\n    loss = ops.mul(ops.sub(ops.ones_like(score), score), weight)\n    return ops.mean(loss)",
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_w",
      "advantage_l"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  }
}

